import React, { useState, useMemo } from "react";
import { Link } from "react-router-dom";
import { useCart } from "react-use-cart";
import products from "../products/Products";
import AllCompo from "../Components/AllCompo";
import Footer from "../Components/Footer";

/* ============================================================
   CATEGORIES
   (نفس التصنيفات الموجودة فعليًا في بيانات المشروع الحالي:
   Rings, Necklaces, Bracelets, Earrings, Chains, Watches)
   ============================================================ */

const CATEGORIES = [
  "All",
  "Rings",
  "Necklaces",
  "Bracelets",
  "Earrings",
  "Chains",
  "Watches",
];

/* ============================================================
   PRODUCTS PAGE (Old Card Design + Current Data)
   ============================================================ */

function Page() {
  const { addItem } = useCart();

  const [search, setSearch] = useState("All");

  const getValue = (value) => {
    setSearch(value);
  };

  const filteredProducts = useMemo(() => {
    if (search === "All") {
      return products;
    }

    return products.filter((item) => item.category === search);
  }, [search]);

  // بنعمل bridge بين شكل بيانات المنتج الحالي (title / thumbnail)
  // وشكل البيانات اللي صفحة الـCart (Cart.js) بتتوقعها (title / images[0])
  // من غير ما نلمس Cart.js خالص
  const handleAddToCart = (item) => {
    addItem({
      id: item.id,
      title: item.title,
      price: Number(item.price) || 0,
      images: [item.thumbnail],
      category: item.category,
      badge: item.badge,
    });
  };

  return (
    <div className="section trending">
      <div className="container">
        <ul className="trending-filter">
          {CATEGORIES.map((cat) => (
            <li key={cat}>
              <button
                type="button"
                className={search === cat ? "active" : ""}
                onClick={() => getValue(cat)}
              >
                {cat}
              </button>
            </li>
          ))}
        </ul>

        <div className="row trending-box">
          {filteredProducts.map((item) => (
            <div
              key={item.id}
              className="col-lg-4 col-md-6 align-self-center mb-30 trending-items"
            >
              <div className="item">
                <div className="thumb">
                  <Link to={`/singleproduct/${item.id}`}>
                    <img src={item.thumbnail} alt={item.title} />
                  </Link>

                  <span className="price">
                    <em>${item.price}</em>
                  </span>

                  <span className="id">
                    <em>{item.id}</em>
                  </span>
                </div>

                <div className="down-content">
                  <span className="category">{item.category}</span>

                  <h4>{item.title}</h4>

                  <button
                    type="button"
                    onClick={() => handleAddToCart(item)}
                  >
                    Add to cart
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredProducts.length === 0 && (
          <p className="no-products">
            لا توجد منتجات في هذا التصنيف حاليًا.
          </p>
        )}
      </div>
    </div>
  );
}

/* ============================================================
   ALL CART (page wrapper)
   ============================================================ */

function AllCart() {
  return (
    <div>
      <AllCompo />
      <Page />
      <Footer />
    </div>
  );
}

export default AllCart;
